    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #202225;
    flex-shrink: 0;
}

.thread-header h4 {
    margin: 0;
    color: #fff;
    font-size: 1rem;
    font-weight: 700;
}

