    color: #b9bbbe;
    font-size: 1.1rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
    transition: background-color 0.1s, color 0.1s;
}

.close-btn:hover {
    background-color: rgba(255, 255, 255, 0.08);
    color: #fff;
}

.thread-root-quote {
    margin: 12px 16px;
    padding: 10px 12px;
    background-color: rgba(0, 0, 0, 0.15);
    border-left: 3px solid #5865f2;
    border-radius: 0 4px 4px 0;
    flex-shrink: 0;
}

.quote-author {
    font-weight: 600;
    color: #fff;
    font-size: 0.85rem;
    margin-bottom: 2px;
}

.quote-content {
    color: #b9bbbe;
    font-size: 0.85rem;
    line-height: 1.3;
    white-space: pre-wrap;
    word-break: break-word;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
    display: flex;
    flex-direction: column;
    gap: 4px;
}

