@using sv_5384633565804a1d9c2285295294fe71.Services

<div class="thread-panel">
    <div class="thread-header">
        <h4>Thread</h4>
        <button class="close-btn" @onclick="OnClose" title="Close thread">✕</button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="thread-root-quote">
            <div class="quote-author">@RootMessage.Author</div>
            <div class="quote-content">@RootMessage.Content</div>
        </div>

        <div class="thread-replies">
            @foreach (var reply in Replies)
            {
                <MessageItem Message="reply"
                             ReplyCount="0"
                             OnOpenThread="OpenThread"
                             OnReact="OnReact" />
            }
        </div>

        <MessageInput Placeholder="Reply to thread…"
                      ButtonLabel="Reply"
                      OnSend="OnSendReply" />
    }
</div>

@code {
    [Parameter] public Message? RootMessage { get; set; }
    [Parameter] public List<Message> Replies { get; set; } = [];
    [Parameter] public EventCallback OnClose { get; set; }
    [Parameter] public EventCallback<string> OnSendReply { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    // Thread panel doesn't open nested threads — ignore
    private EventCallback<int> OpenThread => EventCallback.Factory.Create<int>(this, _ => { });
}

.thread-panel {
    display: flex;
    flex-direction: column;
    height: 100%;
    background-color: #36393f;
    border-left: 1px solid #202225;
    overflow: hidden;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #202225;
    flex-shrink: 0;
}

.thread-header h4 {
    margin: 0;
    color: #fff;
    font-size: 1rem;
    font-weight: 700;
}

.close-btn {
    background: none;
    border: none;
    color: #b9bbbe;
    font-size: 1.1rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
    transition: background-color 0.1s, color 0.1s;
}

.close-btn:hover {
    background-color: rgba(255, 255, 255, 0.08);
    color: #fff;
}

.thread-root-quote {
    margin: 12px 16px;
    padding: 10px 12px;
    background-color: rgba(0, 0, 0, 0.15);
    border-left: 3px solid #5865f2;
    border-radius: 0 4px 4px 0;
    flex-shrink: 0;
}

.quote-author {
    font-weight: 600;
    color: #fff;
    font-size: 0.85rem;
    margin-bottom: 2px;
}

.quote-content {
    color: #b9bbbe;
    font-size: 0.85rem;
    line-height: 1.3;
    white-space: pre-wrap;
    word-break: break-word;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
    display: flex;
    flex-direction: column;
    gap: 4px;
}

